    "history": "신라 시대인 863년(경문왕 3)에 도선 국사가 도봉산에 절을 창건하여 원통사라 하였으며, 1053년(문종 7) 승려 관월 운개(觀月雲開)가 중창하였고, 1392년(태조 1)에 승려 천은 득일(天隱得一)이 삼창하였다. 그 후 조선 영조 때 승려 유인(宥？)이 중수하고 절 이름을 보은사(報恩寺)라 바꾸었다. 또 1810년(순조 10)에 승려 청화(淸和), 1887년(고종 24)에 승려 응허 한규(應虛漢奎)가 중창하였다. 1928년 비구니 자현(慈賢)이 주지로 부임하여 퇴락한 절의 중건을 발원하고 설악산의 승려 춘성(春城)을 청하여 천일 관음 기도를 올려 1929년에 불전을 중건하였다. 승려 보경 보현(寶鏡普賢)을 데려와 아미타불과 지장보살상을 조성하여 봉안하였다. 1931년에 천일기도가 끝나자 그해 겨울에 지리산의 승려 보응과 함께 다시 만일 염불회를 시작하여 1933년에 칠성각을 세우고 1936년에 법당 일부와 큰방을 중수하였으며, 이때에 절 이름을 잠시 보문사(普門寺)로 바꾸기도 하였다. 이후 1938년에 독성각이 세워졌다.",
