    "foundedYear": null,
    "history": "온양읍 운화리 1312번지 대운산 기슭에 자리잡고 있으며 신라시대 대원사의 9암자 중 하나의 암자이다. 내원암은 신라 전통고찰로써 울산광역시 4대고찰(석남사, 문수사, 신흥사)중의 하나로써 지금부터 75년전 을축년에 불이 나서 건물이 전소되었다. 지금 현재 남아있는 구건물 염화실 그 뒤 옛날 칠성각 건물은 을축년에 건립하여 정묘년에 완공한 건물이며, 당시 주지스님은 배덕봉이며, 약 30여 년간 내원암 주지로 계셨다. 구 건물 주지실 묘사채는 최상수 스님이 계실 때 건축한 건물이다. 현재 새로 건축한 대웅전은 1992년 송암스님이 계실 때 건축하여 1993년에 완공을 보고 현재 대웅전 옆 칠성각은 1994년에 완공하였다. 신라시대 대원사의 암자이다. 또 양산시 하북면에 있는 통도사의 말사이다. 신라 불교 전성시대 온양읍 사방에 사사구암이 있었는바 내원암은 당시 그 일암으로써 지금까지 현존하고 있으며 산수미려하여 읍민의 피서지로 명성이 높고 사사구암은 남창의 천안사, 덕신의 영남사, 고사의 안봉사, 삼광의 신흥사, 옥련암 대운산의 대원사 및 안심사말리의 대사등이며 현재까지 그 사지가 남아있다. 백두대간이 남으로 남으로 힘차게 달리다가",
