    "history": "울주군 상북면 덕현리 1064에 여승 수도의 도량으로 자리잡고 있는 석남사(石南寺)는 가지산 보림사의 개종자 도의가 헌덕왕 16년(824)에 창건하였다 한다. 그 후 이조 제 18대 현종 15년 (서기 1674년) 탁영,선철선사에 의하여 중건되고 다시 또 조선 제 23대 순조 3년(서기 1803년) 침허, 수일등의 선사가 중수하였다. 그 후 오랜 세월이 흐르면서 황폐 해진데다가 1950.06.25에 일어난 한국전란으로 폐허는 되었으나 그래도 신라고찰의 모습이 남아있던 것을 모조리 파괴해 버렸던 것이다. 그 후 비구니인 인홍스님께서 주지로 부임해 오자 온통 폐찰이 되다시피 된 석남사를 재건한 것이다. 먼저 대웅전, 극락전, 그 밖의 부속시설을 중수중창을 하고나서 그 다음에 종각, 침계루, 심쇄당, 무진료, 상락료등을 신축하여 사찰의 면모를 일신케 하였다. 석남사는 저 멀리 강원도 태백산맥이 남쪽으로 뻗으면서 줄다름질을 치다가 도중에 경상북도 청도의 운문산을 형성한 뒤 다시 뻗으면서 고헌산맥을 형성했는데, 이 고헌산맥에는 가지산, 신불산간월산, 천황산, 영취산 등의 영산 명봉들을 이루어 놓고 말았다. 가지산에는 석남사, 신불산에는 간월사, 영취산에는 통도사",
