    "name": "금단사",
    "lat": null,
    "lng": null,
    "address": "경기도 파주시 탄현면 성동리 산 78-1",
    "foundedYear": null,
    "history": "금단사는 검단사라고도 하며 탄현면 성동리의 한강과 임진강이 합류하는 부근의 검단산 산허리에 위치한다. 이 절은 신라때 검단조사가 창건했다고 전해지며, 실제로 조선후기에 그려진 검단조사영정 1폭이 전해지고 있어 검단조사와 깊은 관련이 있는 것으로 보인다. 검단조사의 생존연대는 불명확하지만 신라때에 고승이었다고 전해지며 전국 각지에 검단조사와 관련된 창건설을 가진 사찰이 분포하고 있어 주목된다. 혀재 원사지로 생각되는 대지 중심지에는 별다른 건물이 없고 대지 오른쪽에 치우쳐 지금의 사찰이 겨우 잔존하고 있는데 법당인 법화전과 요사채가 남아있다. 법화전은 새로 수리된 부분이 많이 있으나 대체로 조선후기 건축양식을 보이고 있으며, 이절의 유일한 법당으로 사용되고 있는 건물이다. 건물 안에는 불단이 있으며, 불단 위에는 작은 불상이 그 뒤로는 후불정화가 봉안되어 있고 벽면에는 검단조사영정도 걸려 있다. 검단조사영정은 이 절을 창건했다고 알려진검단조사의 영정으로 화면 왼쪽 상단에 검단조사라는 화기가 있다.",
