    "history": "용상사는 월롱산 사면 중턱에 위치하낟. 성종 12년(993), 현종 1년(1010)에 이어 1018년에 소배압이 거느린 10만의 거란군이 개성까지 쳐들어오게 되자 현종은 민복차림으로 이곳 우러롱산까지 피신하게 되었고 다행히 강감찬이 귀주에서 승리하면서 나라안이 평정되자 현종은 이를 기념하기 위하여 절을 짓게 하고 임금이 머물렀다는 뜻으로 용상사라 이름하였다고 한다. 그 뒤 덕은화주가 세종 27년(1445)에 사찰을 중건하였으며 이때 소불석상을 조성해 봉안하였다. 임진왜란때는 승병의 도량이 되었는데 왜군의 시체가 근처 골짜기에 가득하여 한때는 무덤골이라 불리기도 했다고 한며 용상사고지를 현 행정구역명을 따라 덕은리사지라 부르기도 한다. 현재의 용상사는 옛터에서 약간 아래쪽에 터를 닦아 해방전에 중건되었고, 벽장굴에 있던 석불을 대웅전에 모시게 되었다. 1967년에 대웅전을 다시 개축하면서 서쪽에 삼성각을 신축하여 오늘에 이르고 있는데 소속은 대한불교 일승종이다.",
