    "foundedYear": null,
    "history": "설악산 소청봉의 서북쪽에 있는 사찰로 백담사의 부속암자이다. 643년(선덕여왕 12)에 慈藏이 당나라에서 부처님의 眞身舍利를 가지고 귀국하여, 이곳에 사리를 봉안하고 창건하였다. 그 후 677년(문무왕 17)에 元曉大師가, 1188년(명종 18)에 知訥이 중건하였으며, 1518년(중종17)에 幻 寂이 중수하였다. 1548년(명종 3)에는 필마 騰雲(등운)이 중수하였고, 1632년(인조10)에는 雪淨이 중건하였다. 암자 이름을 鳳頂아리고 한 것은 신라 애장왕 때 조상 봉정이 이곳에서 수도하였기 때문에 붙여졌다는 설도 있다. 암자와 석탑 사이의 깊옆의 큰 바위에 “釋迦舍利塔”이란 글자가 각인되어 있다. 현재의 요사채 건물은 1972년 옛 건물터에 증축하였다고 한다. 자연 암반을 이용하여 축대를 쌓고 계단을 만들어 뒤의 법당과 연결하였다.",
