    "history": "보광사(普光寺)는 괴산군 사리면 사담리 산1번지 보광산에 자리한 한국불교태고종 사찰이다. 절의 창건은 정확히 언제인지 기록에 남아 있지 않지만, 1530년대에 편찬된<신증동국여지승람>괴산군(불우조佛宇條)에 절 이름이 보이고 있어 적어도 조선초기에 창건되었음을 알수 있다. 절에 전화는 말로는 17-18세기에는 절에 100여인의 스님이 거주할 정도로 큰 절이었다고 한다. 근대에 와서는 1925년에 폐허가 된 절터에 권봉주(權鳳柱)스님이 초암을 짓고 절으이 법등을 다시 이었고 1936년에는 김봉삼(金奉三)스님이 석불을 봉안하여 중창했다.그런데 이때 봉안한 석불은 역시 폐허였던 부근의 봉학사(鳳鶴寺)터에서 옮겨온 것이다. 전하기로는 이 석불상은 본래 봉학사 법당에 주불로 봉안되었으나 헌종(1834-1849)때 충청도 관찰사 김소(金素)의 후손들이 김소의 묘를 쓰기 위해 절을 허물고 석불의 머리를 자르고 불상을 땅에 묻었다. 그뒤 얼마 안있어 보광산 아래에 사는 한 신도의 꿈에 노승이 세번이나 나타나 불상을 파내라는 계시를 내리는 현몽에 따라서 이불상을 파내어 모셨으며,1936년에 지금의 보광사로 옮겨졌다고한다. 총무 우상기 836-7193",
