    "history": "보석사와 관계된 문헌상의 기록은 『신증동국여지승람(新增東國輿地勝覽)』에 최초로 전한다. 이자료의 「금산군」조에 현존 사찰로 분류되어 실려 있는데, 이로써 본다면 보석사는 16세기 초반 무렵까지 사세를 유지하고 있었음이 확이된다. 이후 『범우고(梵宇攷)』에는 '금폐(今廢)'라고 되어 잇어 18세기 중반에는 이미 폐사의 모습으로 전해지고 있었던 것으로 보인다. 따라서 임진왜란 때 소실되었다고 하는 최근 기록은 나름대로 신빙성이 있어 보이지만, 정확한 폐사 시점에 대해서는 더 검토해 볼 필요가 있다. 18세기부터 이미 폐사로 변해버린 보석사가 언제 중건되었는지는 불분명하다. 다만 현재 일주문 왼쪽에 서있는 「의병승장비(義兵僧將碑)」가 1839년(헌종 6) 5월에 건립되었으므로 이 무렵 언젠가에 중건되었을 가능성이 높아 보인다. 일부 자료에는 고종 때 명성황후(明成皇后), 또는 그의 오빠가 중창하여 오늘에 이르고 있다고 서술되어 있지만, 그것은 「의병승장비」를 세울 당시의 중건 이후에 진행된 또다른 중건 사실로 이해해야 할 것이다.",
