    "history": "용봉사는 용봉산 중턱에 있는 사찰로 옛 문헌에는 영봉사(靈鳳寺)로 기록되어 있다. 현재 2동 26명의 이 사찰은 원래는 현 위치에서 서편에 있는 고지에 있었는데 당시에는 상당히 큰 대찰로 추증되었으나 평양인 조모(趙某)가 사지에 분묘를 조성하기 위하여 권력으로 사찰을 현재의 위치로 이축하였는데 백제의 고찰로 추측되고 도금목질불 4좌가 봉안되어 있다. 용봉사에는 괘불이 보존되어 있거니와 이 괘불의 구성은 강마촉지인을 한 석가모니 불화이다. 이 괘불은 조선 숙종 16년(1690) 5월에 이룩된 화사 진간의 작품이다. 영조1년(1725) 3월 괘불을 중수하면서 불화하단에 왕실의 안녕을 비는 내용을 적고 영조대왕을 찬양하였다. 용봉사에서는 매년 4월초파일에 이 괘불을 대웅전 앞의 석축 위에 걸어놓고 불사를 행한다. 이 탱화가 그려진 연기(緣起)는 숙종대왕이 왕자(균=景宗)을 낳았는데 요절하자 사철에 명을 내려 \"거대한 탱화를 그려 죽은 아들의 명복을 기원케 하라\"하여 숙종 16년에 화사를 파견한 데서 기인된다고 한다. 괘불의 크기는 592*550cm이며 주존의 오른판이 약간 부자연스러운 것 이외는 흠잡을 곳이 없는 뛰어난 작품이다.",
