    "history": "신라 문무왕때 의상대사의 창건이라는 기록과 능인대덕의 창건이라는 기록이 있으나 대체로 능인대덕의 창건으로 보고 있다. 신라 문무왕 12년(672)에 능인대덕이 수도를 한 후 도력으로 종이 봉(鳳)을 만들어 날렸는데, 이 봉이 앉은 곳에 절을 짓고 봉정사라 하였다는 전설이 있다. 현재 이 절에는 부석사의 무량수전과 함께 우리 나라에서 가장 오래된 목조건물로 알려져 있는 극락전을 비롯하여 대웅전, 화엄강당, 고금당 등의 지정문화재와 무량해회, 범종각, 산령각 등의 건물이 있으며 이밖에도 고려시대에 건립된 것으로 보이는 삼층석탑과 경판고(經板庫)에는 대장경 판목이 보관되어있다. 부속암자로는 영산암(靈山庵) 지조암(知照庵) 내원암(內原庵)이있다. 문화재 현황으로는 국보 제15호 봉정사 극락전, 보물 제55호 봉정사 대웅전, 보물 제448호 봉정사 화엄강당, 보물 제449호 봉정사 고금당, 유형 제182호 봉정사 삼층석탑, 유형 제325호 봉정사 만세루, 유형 제328호 봉정사소장유물, 민자 제126호 봉정사 영산암, 문자 제404호 봉정사 동종이 있다.",
