    "history": "부석사는 신라 문무왕 16년(676) 해동화엄종의 종조인 의상대사가 왕명으로 창건한 으뜸 사찰입니다. 대사가 당나라에 유학하고 있을 때 당 고종의 신라 침략 소식을 듣고 이를 왕에게 알리고 그가 닦은 화엄교학 (華嚴敎學)을 펴기 위해 귀국하여 이 절을 창건 우리나라 화엄사상의 발원지가 되었다고 합니다. 그런데, 이 절은 신라 화엄종의 도량(道場)임에도 불구하고 본전인 무량수전에는 아미타불(阿彌陀佛)을 주불 (主佛)로 모셨고, 무량수전 앞에 안양문(安養門)을 세웠으니 『安養』은 곧 『極樂』을 일컬음이니 이 절은 바로 땅 위에 극락세계를 옮겨 놓은 격이 되는 것입니다. 부석사라 이름하게 됨은 무량수전(無量壽殿) 서쪽에 큰 바위가 있는데, 이 바위는 아래의 바위와 서로 붙지 않고 떠 있어 '뜬돌'이라 부른데서 연유하였다고 합니다. 1916년 해체 보수시 발견된 묵서명에 의하면 고려 초기에 무량수전 등을 중창하였으나, 공민왕 7년(1358) 적의 병화를 당하여 우왕 2년(1376) 무량수전이 재건되고, 우왕3년(1377) 조사당(祖師堂)이 재건되었다고 적혀 있습니다.",
