    "history": "대한불교조계종 제2교구 본사인 용주사의 말사이다. 신라 진덕여왕 때(재위 647∼654) 고구려의 침략을 불교의 힘으로 막기 위해 창건한 호국사찰이다. 당시 궁궐에서 기르던 새가 절 주위 숲에 날아와 춤을 추었으므로 봉림사라 하고, 산 이름도 무봉산으로 바꿨다고 한다. 1621년(광해군 13)에 법당과 종각·요사를 중수하였으며, 1708년(숙종 34)에도 중수한 바 있다. 1978년에 목조아미타여래좌상의 복장(腹藏)에서 사리가 발굴되었고, 1979년 이 사리를 봉안한 탑을 세우면서 봉향각과 종각도 다시 지었다. 현존하는 건물로는 대웅전과 봉향각·망양루·범종각·요사채 등이 있고, 유물로는 목조아미타여래좌상과 탱화 여러 점이 전한다. 1978년 대웅전의 목조아미타여래좌상에 금색을 입힐 때 복장에서 불상의 유래를 전하는 기록과 각종 불경이 발견되었는데, 이 기록에 따르면 불상은 1362년(고려 공민왕 11)에 만들어졌다고 하며, 배 부분에서 의상을 U자형으로 처리하고 옷의 주름을 3줄로 표현한 점 등에서 고려 후기의 불상 양식과 일치한다. 눈을 수정으로 만든 점이 특이하다. 1984년 4월 10일 보물 제980호로 지정되었다.",
