    "foundedYear": null,
    "history": "백련사의 본래 이름은 만덕산이란 산 이름을 따서 만덕사라 하였으나 현재는 백련사로 부르고 있다. 이 사찰은 신라말에 창건되었다고 전해지고 있으며 고려 명종때인 1170년 원묘국사 요세에 의해 중창되었다. 특히 요세는 귀족불교에 대한 반발로 서민불교 운동이 한창이던 1232년(고종19년) 보현도장을 개설하고 1236년 (고종 23년) 백련결사문을 발표하여 \"백련결사운동\"을 중창함으로써 백련사가 전국에 널리 알려지는 계기가 되었다. 고려말과 조선초에는 왜구의 잦은 노략질로 폐사가 되다시피 하였으나, 조선초기 세종때 행호주지가 대규모 중창 불사를 하여 옛 모습을 회복하게 되었으며, 조선후기에는 8대사를 배출하여 전국에서 명실공히 으뜸가는 명찰로 알려지기 시작했고, 후기에도 몇차례의 중수가 이루어 졌으며 현재는 대웅전, 응진당, 명부전, 칠성각, 요사채 등의 건물이 남아 있다.",
