    "history": "역사 및 연혁 학서암은 1719년(숙종 45)에 천관사의 승려 화식이 창설하였다. 백운산은 장흥 천관산의 落脈으로 회룡의 기세가 준급하고 백운이 항상 떠나지 않고 있어 산기가 숙정한 까닭에 백운산이라 하였는데, 이 산에 간혹 수액의 변고나 쟁사의 화가 있어 원한이 거듭 일어났다. 이에 이런 여러 액과 화를 제거하고 인명을 구제하기 위하여 이 산에 암자를 세웠다. 그런데 산형이 학형과 같아 암자의 이름을 학서암(鶴棲菴)이라 하였다. 산신 및 불전에 기도하여 액을 없애고 복을 얻게 하여 창설 이래 섬 주민들에게 생활에서 액이나 화가 매우 희소하게 되었다고 전해져 내려온다. 학서암은 주민들의 말에 따르면, 이처럼 300여 년 전에 가구마다 자재를 갹출하고 노동력을 제공하여 백운산에다 설립한 주민단체였다. 그래서 현재도 태풍이나 천재지변에 의해 보수가 필요하면, 불교신자나 기독교신자 또는 비신자를 막론하고 전주민이 직접 노동력을 제공하여 보수공사를 하고 있다.",
