    "history": "ㅇ절 주변에는 신라, 고려시대의 많은 절터가 남아 있다. 이러한 까닭으로 통일신라시대인 767년(혜공왕 3)에 이곳에도 대가람이 있었다고 전하고 있으나 확인할 바가 없다. ㅇ지금의 청룡사는 1925년 청신녀 박문수행(朴文殊行)이 수숫대에 흙을 발라 띠집을 짓고 구도를 시작하면서 비롯됐다. 그 뒤 1964년 이해송(李海松)스님, 1970년 김보안(金保安)스님을 거쳐 1987년부터는 현재의 주지 월담(月潭)스님이 주석하고 있다. ㅇ절의 연혁은 1975년에 건립된 『창건주박문수행공덕비(創建主朴文殊行功德碑)』를 참고할 수 있다. 비문에 의하면 절은 처음 1925년에 3칸의 토굴로 시작했다가 1961년에 3칸의 초가로 법당을 지으면서 청룡암이라 절 이름을 짓고, 1967년에 다시 지금의 법당을 지었으며, 1968년에는 산신각을 지었다고 한다.",
