    "address": "경상북도 영덕군 창수면 장육사1길 172",
    "foundedYear": null,
    "history": "장륙사는 고려말인 공민왕 4년(1355)에 이곳 창수면에서 태어난 나옹혜근(懶翁惠勤, 1320~1376) 스님이 창건하였다고 전한다. 나옹스님 당대에는 매우 번창했던 고찰이나 이후의 자세한 연혁은 전하는 사지(寺誌)가 없어 알 수 없다. 조선시대 들어와 세종 때에 산불로 인하여 사찰 전체가 전소하여 그 후 다시 지었다, 임진왜란 때에도 병화를 입어 폐허가 되었고 그뒤 1900년에 중수하였다. 그러나 광무 4년(1900)에 이현규가 중수하였다는 자료는 문헌을 잘못 해석하여 생긴 오류로 보인다. 이현규가 중수하였다는 절에 전하는「홍원루중건기」현판을 그가 썼기 때문에 그렇게 본듯한데, 실제로 현판의 내용을 자세히 읽어보면, 이현규가 중수한 것이 아니라 여러 契員들의 합심, 그 중에도 특히 황정오&#8228; 이유정&#8228; 김석출 등 세 사람의 노력에 주로 힘입었으며, 중수한 해도 1900년이 아니라 1937년임을 알 수 있다. http://www.koreatemple.net/",
