    "foundedYear": "503",
    "history": "신라 지증왕 4년 범승 연기조사가 창건하여 영악사라 부르다 636년 중건하여 다솔사라 개칭. 다솔사는 오랜 역사를 지니는 고찰로서 대양루는 다솔사 안에 있는 큰 누각으로서, 선조25년(1592)임진왜란이 일어나고 이후 7년 동안 우리나라 대부분의 사찰이 그러했듯이 다솔사도 병화를 입고 폐허되었다 그로부터 거의 100년이 지난 후인 숙종 12년(1686)에 승려들이 힘을 모아 10년 세월에 걸쳐 중창불사로 크게 중흥했다 그러나 62년이 지난후인 영조 24년에 큰불로 말미암아 불행히도 재앙을 겪었다, 그리하여 같은왕(1758)에 여러 스님들이 또 합심하여 명부전과 대양루 사왕문을 중건했다, 그런데 1914년 12월 또한번의 큰불로 모든 전각이 불타는 불운을 겪었으나 이때 유독 대양루만은 그 화를 면하여 오늘에 이르고 있다.",
